package com.shiphappens.logistics.entity;
import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="packages") public class PackageItem { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="package_code") private String packageCode; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="order_id") private LogisticsOrder order; private String description; @Column(name="weight_kg") private BigDecimal weightKg; @Column(name="length_cm") private BigDecimal lengthCm; @Column(name="width_cm") private BigDecimal widthCm; @Column(name="height_cm") private BigDecimal heightCm; @Column(name="declared_value") private BigDecimal declaredValue; public Long getId(){return id;} public String getPackageCode(){return packageCode;} public void setPackageCode(String v){packageCode=v;} public LogisticsOrder getOrder(){return order;} public void setOrder(LogisticsOrder v){order=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public BigDecimal getWeightKg(){return weightKg;} public void setWeightKg(BigDecimal v){weightKg=v;} public void setLengthCm(BigDecimal v){lengthCm=v;} public void setWidthCm(BigDecimal v){widthCm=v;} public void setHeightCm(BigDecimal v){heightCm=v;} public void setDeclaredValue(BigDecimal v){declaredValue=v;} }
